def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    occupied = [[grid[r][c] != bg for c in range(w)] for r in range(h)]

    out = [[bg for _ in range(w)] for _ in range(h)]
    boxes = []

    # Find maximal filled rectangles in the non-background mask.
    for top in range(h):
        valid = [True] * w
        for bottom in range(top, h):
            valid = [valid[c] and occupied[bottom][c] for c in range(w)]
            c = 0
            while c < w:
                if not valid[c]:
                    c += 1
                    continue
                left = c
                while c < w and valid[c]:
                    c += 1
                right = c - 1

                if bottom == top or right == left:
                    continue

                can_extend = False
                if top > 0 and all(occupied[top - 1][x] for x in range(left, right + 1)):
                    can_extend = True
                if bottom + 1 < h and all(occupied[bottom + 1][x] for x in range(left, right + 1)):
                    can_extend = True
                if left > 0 and all(occupied[y][left - 1] for y in range(top, bottom + 1)):
                    can_extend = True
                if right + 1 < w and all(occupied[y][right + 1] for y in range(top, bottom + 1)):
                    can_extend = True

                if not can_extend:
                    boxes.append((top, bottom, left, right))

    for top, bottom, left, right in boxes:
        freq = {}
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                v = grid[r][c]
                freq[v] = freq.get(v, 0) + 1
        color = max(freq, key=freq.get)
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                out[r][c] = color

    return out
